UPDATE companies SET description='A Vintage Wren is a family-owned custom furniture shop based in Goffstown, New Hampshire. Founded by a husband-and-wife team—the woodworker and his partner—the business began in a small house on a rocky hillside where they crafted pieces by hand for local clients.

The company produces made-to-order furniture including farmhouse dining tables, trestle tables, Shaker-style pieces, modern industrial designs, beds, benches, chairs, and accent tables. Every item is handcrafted from domestically sourced hardwoods, with lumber harvested, sawn, and kiln-dried within New Hampshire. The shop offers full customization on dimensions, wood species, and finish.

A Vintage Wren serves residential customers across New England—New Hampshire, Massachusetts, Vermont, Maine, Rhode Island, and Connecticut.

The founders frame their work as an extension of the “farm-to-table” philosophy, emphasizing a local, sustainable economy. By keeping the supply chain within the state, they aim to deliver furniture that carries the story of New Hampshire’s forests into the homes where it will be used for generations.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom furniture design", "Handcrafted woodworking", "Made-to-order production", "Full customization (dimensions, wood species, finish)", "Local lumber sourcing (NH harvested, sawn, kiln-dried)"], "industries": ["Residential furniture", "Custom woodworking", "Home furnishings"], "materials": ["Domestic hardwoods", "Exotic hardwoods", "New Hampshire-sourced lumber (harvested, sawn, kiln-dried locally)"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": [], "facts_used": ["Family-owned custom furniture business in Goffstown, NH -> db", "Handcrafted, made-to-order pieces -> /", "Specializes in farmhouse, modern industrial, trestle, Shaker furniture -> /", "Lumber sourced from NH (harvested, sawn, kiln-dried locally) -> /", "Serves New England states (NH, MA, VT, ME, RI, CT) -> /", "Farm-to-table philosophy, local sustainable economy -> /", "Featured in Fiddlehead Magazine, Boston Voyager, NH Union Leader -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "We are a family owned and operated custom furniture business located in beautiful Goffstown NH, where we work closely with you on your specific needs, creating each unique piece by hand for you.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='a-vintage-wren' AND approved AND profile IS NULL;
UPDATE companies SET description='A.W. Hoss & Son, Inc. has operated from Seattle, Washington since its founding in 1936 by A.W. Hoss.

The shop designs, builds, upholsters, and restores furniture for residential and commercial clients. Capabilities span custom sofas, chairs, banquettes, built-ins, wall panels, and mid-century modern reproductions, using hardwood frames, coil springs, and a range of natural and synthetic fills. The facility houses what the company describes as the largest upholstery showroom in the metro area, stocking commercial-grade fabrics from lines such as Robert Allen, Kravet, and Duralee, alongside a green product line featuring recycled polyester, linen, flax, latex, soy-based foam, and reclaimed wood. A retail section sells DIY upholstery supplies including foam and fabric by the yard.

Hotel and restaurant accounts include Four Seasons, Hyatt Regency, The Westin, W Hotels, and local venues such as Blu Water Bistro and Salish Lodge. Corporate and institutional work covers Microsoft, the University of Washington, Virginia Mason Medical Center, Woodland Park Zoo, and the Frye Art Museum. Retail and entertainment projects have been delivered for Nordstrom, Nike Town, Simon Malls, and the Fifth Avenue Theatre.

